arguments.command:
python3 << 'EOF'
import csv
import statistics
import json
from collections import defaultdict

rows = []
with open('benchmark/data.csv', encoding='utf-8-sig') as f:
    reader = csv.DictReader(f)
    for row in reader:
        rows.append(row)

apps = defaultdict(list)
for row in rows:
    apps[row['App']].append(row)

THEMES = ['Pricing/Subscription', 'Bugs/Performance', 'Accuracy/Logic Issues', 'General']

# KPI 1: Avg Star Rating
star_avgs = {}
for app, app_rows in apps.items():
    ratings = [int(r['Star_Rating']) for r in app_rows]
    star_avgs[app] = round(statistics.mean(ratings), 3)

# KPI 2: Mean Sentiment Polarity
sent_avgs = {}
for app, app_rows in apps.items():
    polarity = [float(r['Sentiment_Polarity']) for r in app_rows]
    sent_avgs[app] = round(statistics.mean(polarity), 4)

# KPI 3: Theme distribution per app
theme_dist = {}
for app, app_rows in apps.items():
    theme_counts = defaultdict(int)
    for r in app_rows:
        theme_counts[r['Review_Theme']] += 1
    total = len(app_rows)
    theme_dist[app] = {t: round(theme_counts[t]/total*100, 2) for t in THEMES}
    theme_dist[app]['_counts'] = {t: theme_counts[t] for t in THEMES}

print("=== THEME DISTRIBUTION ===")
for app, d in theme_dist.items():
    print(f"\n{app}:")
    for t in THEMES:
        print(f"  {t}: {d[t]}% ({d['_counts'][t]})")

# KPI 4: Sentiment-Rating Mismatch
# High star (4-5) with negative polarity (<-0.05) OR low star (1-2) with positive polarity (>0.05)
print("\n=== SENTIMENT-RATING MISMATCH ===")
mismatch_rate = {}
for app, app_rows in apps.items():
    mismatches = 0
    for r in app_rows:
        star = int(r['Star_Rating'])
        pol = float(r['Sentiment_Polarity'])
        if (star >= 4 and pol < -0.05) or (star <= 2 and pol > 0.05):
            mismatches += 1
    rate = round(mismatches / len(app_rows) * 100, 2)
    mismatch_rate[app] = rate
    print(f"{app}: {rate}% ({mismatches}/{len(app_rows)})")

# KPI 5: Avg Thumbs Up
print("\n=== AVG THUMBS UP ===")
thumbs_avgs = {}
for app, app_rows in apps.items():
    thumbs = [int(r['Thumbs_Up_Count']) for r in app_rows]
    thumbs_avgs[app] = round(statistics.mean(thumbs), 3)
    print(f"{app}: {thumbs_avgs[app]}")

# Star rating distributions
print("\n=== STAR RATING DISTRIBUTIONS ===")
star_dist = {}
for app, app_rows in apps.items():
    dist = defaultdict(int)
    for r in app_rows:
        dist[int(r['Star_Rating'])] += 1
    total = len(app_rows)
    star_dist[app] = {s: round(dist[s]/total*100, 1) for s in range(1, 6)}
    print(f"{app}: {star_dist[app]}")

# Word count vs rating/sentiment
print("\n=== AVG WORD COUNT BY STAR ===")
by_star = defaultdict(list)
for r in rows:
    by_star[int(r['Star_Rating'])].append(int(r['Word_Count']))
for s in range(1, 6):
    print(f"Star {s}: avg={round(statistics.mean(by_star[s]),1)} n={len(by_star[s])}")

# Review length correlation with sentiment
print("\n=== AVG WORD COUNT BY APP ===")
for app, app_rows in apps.items():
    wcs = [int(r['Word_Count']) for r in app_rows]
    print(f"{app}: {round(statistics.mean(wcs),1)}")

# Theme thumbs up
print("\n=== AVG THUMBS UP BY THEME ===")
by_theme = defaultdict(list)
for r in rows:
    by_theme[r['Review_Theme']].append(int(r['Thumbs_Up_Count']))
for t, vals in by_theme.items():
    print(f"{t}: {round(statistics.mean(vals),3)} (n={len(vals)})")

